  _globals['_RECOVERTRIGGERDELIVERIESRESPONSE'].fields_by_name['status']._serialized_options = b'\222A\242\0012\224\001The recovery\'s state when this call returned. `running` in practice: the recovery continues after the response, and its later state is not reported.J\t\"running\"'
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['id']._loaded_options = None
