  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['endpoint_id']._loaded_options = None
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['endpoint_id']._serialized_options = b'\222AI21ID of the endpoint this attempt was made against.J\024\"ep_123456789012345\"'
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['msg_id']._loaded_options = None
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['msg_id']._serialized_options = b'\222AP27ID of the trigger event message this attempt delivered.J\025\"msg_123456789012345\"'
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['status']._loaded_options = None
  _globals['_TRIGGERDELIVERYATTEMPT'].fields_by_name['status']._serialized_options = b'\222A\367\0012\351\001Whether this attempt succeeded, is still in flight, or failed. A failed attempt is retried by the delivery application, so FAIL on one attempt does not mean the event was never delivered \342\200\224 check the newest attempt for that message.J\t\"SUCCESS\"'
